        for (int k = 1; k <= n; k++) {
            int 结果 = sc.nextInt();
            if (结果 == 1) {
                System.out.println("第 " + k + " 关：没过");
                栽在第几关 = k;
                break;
            }
            System.out.println("第 " + k + " 关：过");
        }
        if (栽在第几关 == 0) {
            System.out.println("构建成功");
        } else {
            System.out.println("构建失败，停在第 " + 栽在第几关 + " 关");
        }
    }
}

